     1	#pragma once
     2	
     3	// Setting up a model that runs on this computer, in an app such as Ollama or
     4	// LM Studio that answers OpenAI's Responses API at a local address.
     5	//
     6	// Finding asks the app at the address for its models and, where the app is
     7	// one the setup knows, which of them take tools and read pictures. Checking
     8	// is building, as a key check is: one real request with every tool the chat
     9	// offers goes to the model through the agent chats will use, then the app is
    10	// asked how much context it loaded the model with. A model passes when it
    11	// answers and its context holds the app's tools (32k).
    12	//
    13	// GUI-free and poll-driven, like ProviderKeySetup: the app's answers only
    14	// queue, and poll() reads them on the owner's thread. The HTTP client and
    15	// the settings are injected, so the tests drive it with recorded answers.
    16	
    17	#include "AgentService.hpp"
    18	#include "AgentTransport.hpp"
    19	
    20	#include <chrono>
    21	#include <cstdint>
    22	#include <deque>
    23	#include <functional>
    24	#include <memory>
    25	#include <mutex>
    26	#include <optional>
    27	#include <string>
    28	#include <vector>
    29	
    30	namespace Slic3r::GUI::JusPrin::Agent {
    31	
    32	// The model on this computer the person set up: where the app that runs it
    33	// answers, the model's name as that app gives it, which app it is ("Ollama",
    34	// "LM Studio", or empty when the app could not tell), and whether the model
    35	// reads pictures.
    36	struct LocalModelRecord
    37	{
    38	    std::string address;
    39	    std::string model;
    40	    std::string runtime;
    41	    bool        images{true};
    42	
    43	    bool operator==(const LocalModelRecord& other) const
    44	    {
    45	        return address == other.address && model == other.model && runtime == other.runtime && images == other.images;
    46	    }
    47	};
    48	
    49	// One model the app at the address has. `tools` and `images` are unset when
    50	// the app does not say.
    51	struct LocalModelInfo
    52	{
    53	    std::string         id;
    54	    std::optional<bool> tools;
    55	    std::optional<bool> images;
    56	};
    57	
    58	struct LocalModelList
    59	{
    60	    std::string                 address; // normalized_local_address()
    61	    std::string                 runtime; // "Ollama", "LM Studio" or empty
    62	    std::vector<LocalModelInfo> models;
    63	};
    64	
    65	struct LocalSetupOutcome
    66	{
    67	    enum class Kind { Models, Checked, Failed } kind{Kind::Failed};
    68	    LocalModelList   models;  // Models
    69	    LocalModelRecord record;  // Checked: stored already
    70	    AgentServicePtr  service; // Checked: idle, ready to install
    71	    AgentError       error;   // Failed: local_unreachable() or local_cant_run()
    72	    int              elapsed_ms{0};
    73	};
    74	
    75	// The smallest context that holds the app's tools and a turn's messages.
    76	inline constexpr long kLocalMinContext = 32768;
    77	
    78	inline constexpr const char* kRuntimeOllama   = "Ollama";
    79	inline constexpr const char* kRuntimeLmStudio = "LM Studio";
    80	
    81	class LocalModelSetup
    82	{
    83	public:
    84	    // What the app answered one request with. status 0 with `error` set
    85	    // means nothing answered.
    86	    struct Answer
    87	    {
    88	        unsigned    status{0};
    89	        std::string body;
    90	        std::string error;
    91	    };
    92	    // One request to the app: "GET" or "POST" (with a JSON body). `done` is
    93	    // called once, on any thread.
    94	    using Fetch            = std::function<void(const std::string& method, const std::string& url, const std::string& body,
    95	                                     std::function<void(Answer)> done)>;
    96	    using TransportFactory = std::function<std::unique_ptr<IAgentHttpTransport>()>;
    97	    struct Store
    98	    {
    99	        std::function<std::optional<LocalModelRecord>()> load;
   100	        std::function<void(const LocalModelRecord&)>     store;
   101	        std::function<void()>                            remove;
   102	    };
   103	    using Clock = std::function<std::chrono::steady_clock::time_point()>;
   104	
   105	    LocalModelSetup(Fetch fetch, TransportFactory transport, Store store, Clock clock = {});
   106	    ~LocalModelSetup();
   107	
   108	    bool busy() const { return m_step != Step::Idle; }
   109	    // Lists the models at `address` as the person typed it. Throws when busy.
   110	    void find(const std::string& address);
   111	    // Checks `model`, one of the last list's, at that list's address, and
   112	    // stores it when it passes. Throws when busy or for a model not listed.
   113	    void check(const std::string& model);
   114	    void cancel();
   115	    // At most one finished outcome. Throws for an answer that names nothing
   116	    // the person can act on, after stopping; the caller's top handler
   117	    // reports it.
   118	    std::optional<LocalSetupOutcome> poll();
   119	
   120	    std::optional<LocalModelRecord> saved() const;
   121	    void                            remove();
   122	
   123	private:
   124	    enum class Step { Idle, Models, Version, Show, LmsModels, Probe, LoadedContext };
   125	    // Where the app's answers wait for poll(). Shared with the requests in
   126	    // flight, which may answer after the setup is gone.
   127	    struct Answers
   128	    {
   129	        std::mutex         mutex;
   130	        std::deque<Answer> queue;
   131	        std::uint64_t      generation{0};
   132	    };
   133	
   134	    void                             request(const std::string& method, const std::string& path, const std::string& body = {});
   135	    std::optional<LocalSetupOutcome> advance(const Answer& answer);
   136	    std::optional<LocalSetupOutcome> next_show();
   137	    std::optional<LocalSetupOutcome> start_probe();
   138	    std::optional<LocalSetupOutcome> poll_probe();
   139	    LocalSetupOutcome                failed(AgentError error);
   140	    LocalSetupOutcome                checked();
   141	    [[noreturn]] void                unexpected(const std::string& what, const Answer& answer);
   142	    void                             stop();
   143	    int                              elapsed_ms() const;
   144	
   145	    Fetch            m_fetch;
   146	    TransportFactory m_transport;
   147	    Store            m_store;
   148	    Clock            m_clock;
   149	
   150	    std::shared_ptr<Answers> m_answers{std::make_shared<Answers>()};
   151	
   152	    Step                                  m_step{Step::Idle};
   153	    std::chrono::steady_clock::time_point m_started{};
   154	    LocalModelList                        m_list;
   155	    std::size_t                           m_showing{0}; // the model /api/show is asked about
   156	    std::string                           m_checking;
   157	    AgentServicePtr                       m_candidate;
   158	};
   159	
   160	} // namespace Slic3r::GUI::JusPrin::Agent

