 12	#include <string>
 13	#include <utility>
 14	
 15	namespace Slic3r::GUI::JusPrin::Agent {
 16	
 17	namespace {
 18	
 19	using json = nlohmann::json;
 20	
 21	json parsed(const std::string& body) { return json::parse(body, nullptr, false); }
 22	
 23	bool has(const json& list, const char* item)
 24	{
 25	    return list.is_array() && std::find(list.begin(), list.end(), item) != list.end();
 26	}
 27	
 28	// What the app answered, for the report of an answer that names nothing the
 29	// person can act on.
 30	std::string said(const LocalModelSetup::Answer& answer)
 31	{
 32	    return "answered " + std::to_string(answer.status) + (answer.error.empty() ? "" : " (" + answer.error + ")") + ": " +
 33	           answer.body.substr(0, 2048);
 34	}
 35	
 36	} // namespace
 37	
 38	LocalModelSetup::LocalModelSetup(Fetch fetch, TransportFactory transport, Store store, Clock clock)
 39	    : m_fetch(std::move(fetch)), m_transport(std::move(transport)), m_store(std::move(store)), m_clock(std::move(clock))
 40	{
 41	    if (!m_clock)
 42	        m_clock = []() { return std::chrono::steady_clock::now(); };
 43	}
 44	
 45	LocalModelSetup::~LocalModelSetup() { stop(); }
 46	
 47	void LocalModelSetup::find(const std::string& address)
 48	{
 49	    if (busy())
 50	        throw std::logic_error("jusprin-local-setup: finding models while setup runs");
 51	    m_list         = LocalModelList{};
 52	    m_list.address = normalized_local_address(address);
 53	    if (m_list.address.empty())
 54	        throw std::runtime_error("jusprin-local-setup: finding models at an empty address");
 55	    m_started = m_clock();
 56	    m_step    = Step::Models;
 57	    request("GET", "/v1/models");
 58	}
 59	
 60	void LocalModelSetup::check(const std::string& model)
 61	{
 62	    if (busy())
 63	        throw std::logic_error("jusprin-local-setup: checking a model while setup runs");
 64	    const auto listed = std::find_if(m_list.models.begin(), m_list.models.end(),
 65	                                     [&](const LocalModelInfo& info) { return info.id == model; });
 66	    // The page offers the last list's models only.
 67	    if (listed == m_list.models.end())
 68	        throw std::runtime_error("jusprin-local-setup: checking " + model + ", which the last list at " + m_list.address +
 69	                                 " does not have");
 70	    m_checking = model;
 71	    m_started  = m_clock();
 72	    m_step     = Step::Probe;
 73	}
 74	
 75	void LocalModelSetup::cancel() { stop(); }
 76	
 77	void LocalModelSetup::stop()
 78	{
 79	    {
 80	        std::lock_guard<std::mutex> lock(m_answers->mutex);
 81	        ++m_answers->generation;
 82	        m_answers->queue.clear();
 83	    }
 84	    if (m_candidate)
 85	        m_candidate->cancel();
 86	    m_candidate.reset();
 87	    m_step = Step::Idle;
 88	}
 89	
 90	void LocalModelSetup::request(const std::string& method, const std::string& path, const std::string& body)
 91	{
 92	    std::uint64_t generation;
 93	    {
 94	        std::lock_guard<std::mutex> lock(m_answers->mutex);
 95	        generation = m_answers->generation;
 96	    }
 97	    m_fetch(method, m_list.address + path, body, [answers = m_answers, generation](Answer answer) {
 98	        std::lock_guard<std::mutex> lock(answers->mutex);
 99	        if (generation == answers->generation)
100	            answers->queue.push_back(std::move(answer));
101	    });
102	}
103	
104	std::optional<LocalSetupOutcome> LocalModelSetup::poll()
105	{
106	    if (m_step == Step::Probe)
107	        return poll_probe();
108	    while (busy()) {
109	        Answer answer;
110	        {
111	            std::lock_guard<std::mutex> lock(m_answers->mutex);
112	            if (m_answers->queue.empty())
113	                return std::nullopt;
114	            answer = std::move(m_answers->queue.front());
115	            m_answers->queue.pop_front();
116	        }
117	        if (std::optional<LocalSetupOutcome> outcome = advance(answer))
118	            return outcome;
119	        if (m_step == Step::Probe)
120	            return poll_probe();
121	    }
122	    return std::nullopt;
123	}
124	
125	std::optional<LocalSetupOutcome> LocalModelSetup::advance(const Answer& answer)
126	{
127	    const json body = parsed(answer.body);
128	    switch (m_step) {
129	    case Step::Models: {
130	        // Nothing answered: the app that runs the model is not running, or
131	        // the address is wrong. Either way the person starts it or fixes it.
132	        if (answer.status == 0)
133	            return failed(local_unreachable(m_list.address));
134	        if (answer.status != 200 || !body.is_object() || !body.contains("data") || !body["data"].is_array())
135	            unexpected("listing its models", answer);
136	        for (const json& entry : body["data"])
137	            if (entry.is_object() && entry.contains("id") && entry["id"].is_string())
138	                m_list.models.push_back({entry["id"].get<std::string>(), std::nullopt, std::nullopt});
139	        m_step = Step::Version;
140	        request("GET", "/api/version");
141	        return std::nullopt;
142	    }
143	    case Step::Version:
144	        // Ollama answers its own version; LM Studio and others do not.
145	        if (answer.status == 200 && body.is_object() && body.contains("version")) {
146	            m_list.runtime = kRuntimeOllama;
147	            m_showing      = 0;
148	            return next_show();
149	        }
150	        m_step = Step::LmsModels;
151	        request("GET", "/api/v1/models");
152	        return std::nullopt;
153	    case Step::Show: {
154	        if (answer.status != 200 || !body.is_object())
155	            unexpected("describing " + m_list.models[m_showing].id, answer);
156	        const json capabilities = body.value("capabilities", json::array());
157	        LocalModelInfo& info = m_list.models[m_showing];
158	        // An embedding model writes no replies; it is no chat's model.
159	        if (!has(capabilities, "completion")) {
160	            m_list.models.erase(m_list.models.begin() + static_cast<std::ptrdiff_t>(m_showing));
161	        } else {
162	            info.tools  = has(capabilities, "tools");
163	            info.images = has(capabilities, "vision");
164	            ++m_showing;
165	        }
166	        return next_show();
167	    }
168	    case Step::LmsModels: {
169	        // An app that is not LM Studio either: what its models can do is
170	        // unknown, and the check finds out whether they run.
171	        if (answer.status != 200 || !body.is_object() || !body.contains("models") || !body["models"].is_array()) {
172	            m_step = Step::Idle;
173	            LocalSetupOutcome outcome;
174	            outcome.kind       = LocalSetupOutcome::Kind::Models;
175	            outcome.models     = m_list;
176	            outcome.elapsed_ms = elapsed_ms();
177	            return outcome;
178	        }
179	        m_list.runtime = kRuntimeLmStudio;
180	        std::vector<LocalModelInfo> kept;
181	        for (LocalModelInfo info : m_list.models) {
182	            const auto entry = std::find_if(body["models"].begin(), body["models"].end(), [&](const json& model) {
183	                return model.is_object() && model.value("key", "") == info.id;
184	            });
185	            if (entry != body["models"].end()) {
186	                if (entry->value("type", "") == "embedding")
187	                    continue;
188	                const json capabilities = entry->value("capabilities", json::object());
189	                if (capabilities.is_object()) {
190	                    if (capabilities.contains("trained_for_tool_use") && capabilities["trained_for_tool_use"].is_boolean())
191	                        info.tools = capabilities["trained_for_tool_use"].get<bool>();
192	                    if (capabilities.contains("vision") && capabilities["vision"].is_boolean())
193	                        info.images = capabilities["vision"].get<bool>();
194	                }
195	            }
196	            kept.push_back(std::move(info));
197	        }
198	        m_list.models = std::move(kept);
199	        m_step        = Step::Idle;
200	        LocalSetupOutcome outcome;
201	        outcome.kind       = LocalSetupOutcome::Kind::Models;
202	        outcome.models     = m_list;
203	        outcome.elapsed_ms = elapsed_ms();
204	        return outcome;
205	    }
206	    case Step::LoadedContext: {
207	        if (answer.status != 200 || !body.is_object())
208	            unexpected("saying how much context " + m_checking + " was loaded with", answer);
209	        std::optional<long> context;
210	        if (m_list.runtime == kRuntimeOllama) {
211	            for (const json& loaded : body.value("models", json::array()))
212	                if (loaded.is_object() && (loaded.value("name", "") == m_checking || loaded.value("model", "") == m_checking) &&
213	                    loaded.contains("context_length") && loaded["context_length"].is_number_integer())
214	                    context = loaded["context_length"].get<long>();
215	        } else {
216	            for (const json& model : body.value("models", json::array()))
217	                if (model.is_object() && model.value("key", "") == m_checking)
218	                    for (const json& instance : model.value("loaded_instances", json::array()))
219	                        if (instance.is_object() && instance.contains("config") && instance["config"].is_object() &&
220	                            instance["config"].contains("context_length") &&
221	                            instance["config"]["context_length"].is_number_integer())
222	                            context = instance["config"]["context_length"].get<long>();
223	        }
224	        if (!context)
225	            unexpected("saying how much context " + m_checking + " was loaded with", answer);
226	        if (*context < kLocalMinContext)
227	            return failed(local_cant_run());
228	        return checked();
229	    }
230	    case Step::Idle:
231	    case Step::Probe:
232	        break;
233	    }
234	    throw std::logic_error("jusprin-local-setup: an answer with no request waiting for it");
235	}
236	
237	std::optional<LocalSetupOutcome> LocalModelSetup::next_show()
238	{
239	    if (m_showing < m_list.models.size()) {
240	        m_step = Step::Show;
241	        request("POST", "/api/show", json{{"model", m_list.models[m_showing].id}}.dump());
242	        return std::nullopt;
243	    }
244	    m_step = Step::Idle;
245	    LocalSetupOutcome outcome;
246	    outcome.kind       = LocalSetupOutcome::Kind::Models;
247	    outcome.models     = m_list;
248	    outcome.elapsed_ms = elapsed_ms();
249	    return outcome;
250	}
251	
252	std::optional<LocalSetupOutcome> LocalModelSetup::start_probe()
253	{
254	    const auto listed = std::find_if(m_list.models.begin(), m_list.models.end(),
255	                                     [&](const LocalModelInfo& info) { return info.id == m_checking; });
256	    // The app says the model takes no tools: the check would only fail.
257	    if (listed->tools == false)
258	        return failed(local_cant_run());
259	    m_candidate = make_provider_agent(*profile_for(kLocalProvider), {}, m_checking, local_endpoint(m_list.address), m_transport());
260	    if (!m_candidate->start(setup_probe_request()))
261	        throw std::logic_error("jusprin-local-setup: the check's agent would not start");
262	    return std::nullopt;
263	}
264	
265	std::optional<LocalSetupOutcome> LocalModelSetup::poll_probe()
266	{
267	    if (!m_candidate)
268	        if (std::optional<LocalSetupOutcome> refused = start_probe())
269	            return refused;
270	    while (const std::optional<AgentEvent> event = m_candidate->poll()) {
271	        switch (event->kind) {
272	        case AgentEventKind::TextDelta:
273	            break; // What it says is irrelevant; that it answers is the test.
274	        case AgentEventKind::ToolCall:
275	        case AgentEventKind::Completed:
276	            // It answered with the app's tools offered. An app that cannot
277	            // say how much context it loaded the model with is not asked.
278	            m_candidate->cancel();
279	            if (m_list.runtime.empty())
280	                return checked();
281	            m_step = Step::LoadedContext;
282	            request("GET", m_list.runtime == kRuntimeOllama ? "/api/ps" : "/api/v1/models");
283	            return std::nullopt;
284	        case AgentEventKind::Failed:
285	            if (!event->error)
286	                throw std::logic_error("jusprin-local-setup: the check failed with no error");
287	            return failed(*event->error);
288	        }
289	    }
290	    return std::nullopt;
291	}
292	
293	LocalSetupOutcome LocalModelSetup::failed(AgentError error)
294	{
295	    LocalSetupOutcome outcome;
296	    outcome.kind       = LocalSetupOutcome::Kind::Failed;
297	    outcome.error      = std::move(error);
298	    outcome.elapsed_ms = elapsed_ms();
299	    stop();
300	    return outcome;
301	}
302	
303	LocalSetupOutcome LocalModelSetup::checked()
304	{
305	    const auto listed = std::find_if(m_list.models.begin(), m_list.models.end(),
306	                                     [&](const LocalModelInfo& info) { return info.id == m_checking; });
307	    LocalSetupOutcome outcome;
308	    outcome.kind = LocalSetupOutcome::Kind::Checked;
309	    // A model the app says nothing about gets no pictures: sending one to a
310	    // model that cannot read it fails the turn.
311	    outcome.record     = {m_list.address, m_checking, m_list.runtime, listed->images.value_or(false)};
312	    outcome.elapsed_ms = elapsed_ms();
313	    m_store.store(outcome.record);
314	    {
315	        std::lock_guard<std::mutex> lock(m_answers->mutex);
316	        ++m_answers->generation;
317	        m_answers->queue.clear();
318	    }
319	    outcome.service = std::move(m_candidate);
320	    m_candidate.reset();
321	    m_step = Step::Idle;
322	    return outcome;
323	}
