 47	void LocalModelSetup::find(const std::string& address)
 48	{
 49	    if (busy())
 50	        throw std::logic_error("jusprin-local-setup: finding models while setup runs");
 51	    m_list         = LocalModelList{};
 52	    m_list.address = normalized_local_address(address);
