 60	void LocalModelSetup::check(const std::string& model)
 61	{
 62	    if (busy())
 63	        throw std::logic_error("jusprin-local-setup: checking a model while setup runs");
 64	    const auto listed = std::find_if(m_list.models.begin(), m_list.models.end(),
 65	                                     [&](const LocalModelInfo& info) { return info.id == model; });
 66	    // The page offers the last list's models only.
 67	    if (listed == m_list.models.end())
 68	        throw std::runtime_error("jusprin-local-setup: checking " + model + ", which the last list at " + m_list.address +
 69	                                 " does not have");
 70	    m_checking = model;
 71	    m_started  = m_clock();
 72	    m_step     = Step::Probe;
 73	}
