 77	void LocalModelSetup::stop()
 78	{
 79	    {
 80	        std::lock_guard<std::mutex> lock(m_answers->mutex);
 81	        ++m_answers->generation;
 82	        m_answers->queue.clear();
 83	    }
 84	    if (m_candidate)
 85	        m_candidate->cancel();
 86	    m_candidate.reset();
 87	    m_step = Step::Idle;
