 90	void LocalModelSetup::request(const std::string& method, const std::string& path, const std::string& body)
 91	{
 92	    std::uint64_t generation;
 93	    {
 94	        std::lock_guard<std::mutex> lock(m_answers->mutex);
 95	        generation = m_answers->generation;
 96	    }
 97	    m_fetch(method, m_list.address + path, body, [answers = m_answers, generation](Answer answer) {
 98	        std::lock_guard<std::mutex> lock(answers->mutex);
 99	        if (generation == answers->generation)
100	            answers->queue.push_back(std::move(answer));
101	    });
102	}
