104	std::optional<LocalSetupOutcome> LocalModelSetup::poll()
105	{
106	    if (m_step == Step::Probe)
107	        return poll_probe();
108	    while (busy()) {
109	        Answer answer;
110	        {
111	            std::lock_guard<std::mutex> lock(m_answers->mutex);
112	            if (m_answers->queue.empty())
113	                return std::nullopt;
114	            answer = std::move(m_answers->queue.front());
115	            m_answers->queue.pop_front();
116	        }
117	        if (std::optional<LocalSetupOutcome> outcome = advance(answer))
118	            return outcome;
119	        if (m_step == Step::Probe)
120	            return poll_probe();
121	    }
122	    return std::nullopt;
123	}
