125	std::optional<LocalSetupOutcome> LocalModelSetup::advance(const Answer& answer)
126	{
127	    const json body = parsed(answer.body);
128	    switch (m_step) {
129	    case Step::Models: {
130	        // Nothing answered: the app that runs the model is not running, or
131	        // the address is wrong. Either way the person starts it or fixes it.
132	        if (answer.status == 0)
133	            return failed(local_unreachable(m_list.address));
134	        if (answer.status != 200 || !body.is_object() || !body.contains("data") || !body["data"].is_array())
135	            unexpected("listing its models", answer);
136	        for (const json& entry : body["data"])
137	            if (entry.is_object() && entry.contains("id") && entry["id"].is_string())
138	                m_list.models.push_back({entry["id"].get<std::string>(), std::nullopt, std::nullopt});
139	        m_step = Step::Version;
140	        request("GET", "/api/version");
141	        return std::nullopt;
142	    }
143	    case Step::Version:
144	        // Ollama answers its own version; LM Studio and others do not.
145	        if (answer.status == 200 && body.is_object() && body.contains("version")) {
146	            m_list.runtime = kRuntimeOllama;
147	            m_showing      = 0;
148	            return next_show();
149	        }
150	        m_step = Step::LmsModels;
151	        request("GET", "/api/v1/models");
152	        return std::nullopt;
153	    case Step::Show: {
154	        if (answer.status != 200 || !body.is_object())
155	            unexpected("describing " + m_list.models[m_showing].id, answer);
156	        const json capabilities = body.value("capabilities", json::array());
157	        LocalModelInfo& info = m_list.models[m_showing];
158	        // An embedding model writes no replies; it is no chat's model.
159	        if (!has(capabilities, "completion")) {
160	            m_list.models.erase(m_list.models.begin() + static_cast<std::ptrdiff_t>(m_showing));
161	        } else {
162	            info.tools  = has(capabilities, "tools");
163	            info.images = has(capabilities, "vision");
164	            ++m_showing;
165	        }
166	        return next_show();
167	    }
168	    case Step::LmsModels: {
169	        // An app that is not LM Studio either: what its models can do is
170	        // unknown, and the check finds out whether they run.
171	        if (answer.status != 200 || !body.is_object() || !body.contains("models") || !body["models"].is_array()) {
172	            m_step = Step::Idle;
173	            LocalSetupOutcome outcome;
174	            outcome.kind       = LocalSetupOutcome::Kind::Models;
175	            outcome.models     = m_list;
176	            outcome.elapsed_ms = elapsed_ms();
177	            return outcome;
178	        }
179	        m_list.runtime = kRuntimeLmStudio;
180	        std::vector<LocalModelInfo> kept;
181	        for (LocalModelInfo info : m_list.models) {
182	            const auto entry = std::find_if(body["models"].begin(), body["models"].end(), [&](const json& model) {
183	                return model.is_object() && model.value("key", "") == info.id;
184	            });
185	            if (entry != body["models"].end()) {
186	                if (entry->value("type", "") == "embedding")
187	                    continue;
188	                const json capabilities = entry->value("capabilities", json::object());
189	                if (capabilities.is_object()) {
190	                    if (capabilities.contains("trained_for_tool_use") && capabilities["trained_for_tool_use"].is_boolean())
191	                        info.tools = capabilities["trained_for_tool_use"].get<bool>();
192	                    if (capabilities.contains("vision") && capabilities["vision"].is_boolean())
193	                        info.images = capabilities["vision"].get<bool>();
194	                }
195	            }
196	            kept.push_back(std::move(info));
197	        }
198	        m_list.models = std::move(kept);
199	        m_step        = Step::Idle;
200	        LocalSetupOutcome outcome;
201	        outcome.kind       = LocalSetupOutcome::Kind::Models;
202	        outcome.models     = m_list;
203	        outcome.elapsed_ms = elapsed_ms();
204	        return outcome;
205	    }
206	    case Step::LoadedContext: {
207	        if (answer.status != 200 || !body.is_object())
208	            unexpected("saying how much context " + m_checking + " was loaded with", answer);
209	        std::optional<long> context;
210	        if (m_list.runtime == kRuntimeOllama) {
211	            for (const json& loaded : body.value("models", json::array()))
212	                if (loaded.is_object() && (loaded.value("name", "") == m_checking || loaded.value("model", "") == m_checking) &&
213	                    loaded.contains("context_length") && loaded["context_length"].is_number_integer())
214	                    context = loaded["context_length"].get<long>();
215	        } else {
216	            for (const json& model : body.value("models", json::array()))
217	                if (model.is_object() && model.value("key", "") == m_checking)
218	                    for (const json& instance : model.value("loaded_instances", json::array()))
219	                        if (instance.is_object() && instance.contains("config") && instance["config"].is_object() &&
220	                            instance["config"].contains("context_length") &&
221	                            instance["config"]["context_length"].is_number_integer())
222	                            context = instance["config"]["context_length"].get<long>();
223	        }
224	        if (!context)
225	            unexpected("saying how much context " + m_checking + " was loaded with", answer);
226	        if (*context < kLocalMinContext)
227	            return failed(local_cant_run());
228	        return checked();
229	    }
230	    case Step::Idle:
231	    case Step::Probe:
232	        break;
233	    }
234	    throw std::logic_error("jusprin-local-setup: an answer with no request waiting for it");
235	}
