293	LocalSetupOutcome LocalModelSetup::failed(AgentError error)
294	{
295	    LocalSetupOutcome outcome;
296	    outcome.kind       = LocalSetupOutcome::Kind::Failed;
297	    outcome.error      = std::move(error);
298	    outcome.elapsed_ms = elapsed_ms();
299	    stop();
300	    return outcome;
301	}
